SELECT /*selectMasterMdAmAuthorityManageList*/ A.AUTH_ID , A.NAME AS AUTH_NAME , A.AUTH_DC , A.CREATE_DT , A.USE_FLAG , A.ROLE_FLAG ,(SELECT COUNT(*) FROM KX_MENUAUTH WHERE AUTH_ID = A.AUTH_ID AND USE_FLAG ='Y') AS ROLE_MENU_CNT ,(SELECT COUNT(*) FROM KX_USERAUTH WHERE AUTH_ID = A.AUTH_ID AND USE_FLAG ='Y') AS ROLE_USER_G_CNT ,(SELECT COUNT(*) FROM KX_USERROLE WHERE ROLE_ID = A.AUTH_ID AND USE_FLAG ='Y') AS ROLE_USER_S_CNT FROM KX_AUTHINFO A WHERE 1=1
AND A.AUTH_ID LIKE '%' || #{st_auth_id} || '%'
AND A.NAME LIKE '%' || #{st_auth_name} || '%'
AND A.CREATE_DT BETWEEN #{st_from_date} AND #{st_to_date}
AND A.USE_FLAG = #{st_use_flag}
AND A.ROLE_FLAG = #{st_role_flag}
ORDER BY AUTH_ID, AUTH_NAME

mapper.update:
/*updateMasterMdAmAuthorityManage*/
		UPDATE KX_AUTHINFO					
		SET   NAME = #{AUTH_NAME},
				AUTH_DC = #{AUTH_DC},
				USE_FLAG = #{USE_FLAG},
				ROLE_FLAG= #{ROLE_FLAG}							
		WHERE AUTH_ID = #{AUTH_ID}
